"""`wasm_manifest` fixture builders (task 2.12).

Wasm here is a generated byte string (`ARCHITECTURE.md` 12): the magic header, a version preamble
and one custom section naming the seed. It is not a compiled contract, and the hashes a manifest
entry carries are computed from these bytes when the builder runs, so a fixture never cites a hash
of something the repository does not hold.
"""

from __future__ import annotations

from airlock.model import Manifest, WasmEntry

from . import Case, File, Fixture, digest

ARTIFACT = "contracts/export_min.wasm"
ELSEWHERE = "contracts/facilitator.wasm"
MISSING = "contracts/smart_account.wasm"
ARCHIVE = "vendor/artifacts.zip"

WASM_MAGIC = b"\x00asm"
WASM_VERSION = b"\x01\x00\x00\x00"
ZIP_MAGIC = b"PK\x03\x04"


def wasm_bytes(seed: int) -> bytes:
    """A Wasm-shaped byte string, distinct for each seed."""
    name = f"airlock_synthetic_{seed}".encode()
    section = WASM_MAGIC + WASM_VERSION + b"\x00" + bytes([len(name) * 2 + 1]) + name + name
    return section


def lfs_pointer(seed: int) -> str:
    """The git LFS pointer shape: a file named `*.wasm` that holds no Wasm header."""
    return f"version https://git-lfs.github.com/spec/v1\noid sha256:{digest(wasm_bytes(seed))}\n"


def listed(data: bytes, path: str) -> Case:
    """One artifact plus the manifest entry that vouches for it at that path."""
    entry = WasmEntry(
        sha256=digest(data),
        paths=(path,),
        origin="built",
        source="cargo-contract",
        build="cargo contract build",
        note="synthetic fixture",
    )
    return Case(files=(File(path, raw=data),), manifest=Manifest(entries=(entry,)))


def entry_for(data: bytes, path: str, origin: str = "built") -> WasmEntry:
    return WasmEntry(
        sha256=digest(data),
        paths=(path,),
        origin=origin,
        source="cargo-contract" if origin == "built" else "upstream release",
        build="cargo contract build" if origin == "built" else "downloaded",
        note="synthetic fixture",
    )


def wasm_unlisted() -> Fixture:
    return Fixture(
        positive=Case(
            files=(
                File(ARTIFACT, raw=wasm_bytes(7)),
                File(MISSING, text=lfs_pointer(8)),
            )
        ),
        negative=listed(wasm_bytes(7), ARTIFACT),
    )


def wasm_hash_mismatch() -> Fixture:
    """The path is listed and the bytes are not: a swapped artifact is HIGH."""
    return Fixture(
        positive=Case(
            files=(File(ARTIFACT, raw=wasm_bytes(3)),),
            manifest=Manifest(entries=(entry_for(wasm_bytes(4), ARTIFACT, "vendored"),)),
        ),
        negative=listed(wasm_bytes(4), ARTIFACT),
    )


def wasm_path_moved() -> Fixture:
    """The known artifact at an unexpected path: a WARN, because the bytes are still audited."""
    data = wasm_bytes(5)
    return Fixture(
        positive=Case(
            files=(File(ELSEWHERE, raw=data),),
            manifest=Manifest(entries=(entry_for(data, ARTIFACT),)),
        ),
        negative=listed(data, ARTIFACT),
    )


def wasm_manifest_stale() -> Fixture:
    return Fixture(
        positive=Case(
            files=(File("src/lib.rs", text="pub fn store(k: &[u8]) {}\n"),),
            manifest=Manifest(entries=(entry_for(wasm_bytes(6), MISSING),)),
        ),
        negative=listed(wasm_bytes(6), MISSING),
    )


def wasm_archive_skipped() -> Fixture:
    """An archive is declared skipped: nothing inside it was compared, so the scan says so."""
    return Fixture(
        positive=Case(files=(File(ARCHIVE, raw=ZIP_MAGIC + b"\x00" * 40),)),
        negative=Case(files=(File("vendor/artifacts.md", text="# artifacts\n"),)),
    )


BUILDERS = {
    "wasm_unlisted": wasm_unlisted,
    "wasm_hash_mismatch": wasm_hash_mismatch,
    "wasm_path_moved": wasm_path_moved,
    "wasm_manifest_stale": wasm_manifest_stale,
    "wasm_archive_skipped": wasm_archive_skipped,
}
